import pandas as pd


def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"]
    cdc_events = inputs["cdc_events"]
    watermark = inputs["watermark"]

    # Determine watermark high_ts
    if len(watermark) > 0:
        high_ts = watermark["high_ts"].max()
    else:
        high_ts = None

    # Filter events that are not yet applied (event_ts > high_ts)
    if high_ts is not None:
        events = cdc_events[cdc_events["event_ts"] > high_ts].copy()
    else:
        events = cdc_events.copy()

    # Sort events per item, then by event_ts, then event_seq for sequential application
    events = events.sort_values(by=["item_id", "event_ts", "event_seq"],
                                 kind="mergesort")

    # Build initial state from target_snapshot
    state = {}
    for row in target_snapshot.itertuples(index=False):
        state[row.item_id] = {
            "qty": float(row.qty_on_hand),
            "ts": row.last_event_ts,
            "exists": True,
        }

    # Apply events sequentially per item
    for row in events.itertuples(index=False):
        item_id = row.item_id
        op = row.op
        qty = row.qty
        ts = row.event_ts

        if item_id not in state:
            state[item_id] = {"qty": 0.0, "ts": None, "exists": False}

        s = state[item_id]

        if op == "R":
            if s["exists"]:
                s["qty"] = s["qty"] + qty
            else:
                # recreate starting from 0
                s["qty"] = 0.0 + qty
                s["exists"] = True
        elif op == "A":
            s["qty"] = qty
            s["exists"] = True
        elif op == "D":
            s["exists"] = False
            # qty value irrelevant while deleted; keep as-is or reset,
            # doesn't matter since not exists until recreated

        s["ts"] = ts

    # Build output snapshot from items that exist
    records = []
    for item_id, s in state.items():
        if s["exists"]:
            records.append({
                "item_id": item_id,
                "qty_on_hand": s["qty"],
                "last_event_ts": s["ts"],
            })

    if records:
        new_snapshot = pd.DataFrame.from_records(records)
        new_snapshot = new_snapshot.astype({
            "item_id": "int64",
            "qty_on_hand": "float64",
        })
        new_snapshot["last_event_ts"] = pd.to_datetime(new_snapshot["last_event_ts"])
        new_snapshot = new_snapshot.sort_values(by="item_id").reset_index(drop=True)
    else:
        new_snapshot = pd.DataFrame({
            "item_id": pd.Series(dtype="int64"),
            "qty_on_hand": pd.Series(dtype="float64"),
            "last_event_ts": pd.Series(dtype="datetime64[us]"),
        })

    return {"new_snapshot": new_snapshot}
